package shared

import (
	"strings"
	"testing"
)

func TestIsGeneratedSource(t *testing.T) {
	cases := map[string]bool{
		"// Code generated by protoc-gen-go. DO NOT EDIT.\n\npackage pb\n":                  true,
		"// Copyright 2020\n\n// Code generated by \"stringer\"; DO NOT EDIT.\npackage x\n": true,
		"/**\n * @generated SignedSource<<abc>>\n */\nexport const x = 1;\n":                true,
		"package main\n\n// Code generated is mentioned here but not as a marker\n":         false,
		"export function App() { return null }\n":                                           false,
	}
	for src, want := range cases {
		if got := IsGeneratedSource([]byte(src)); got != want {
			t.Errorf("IsGeneratedSource(%q) = %v, want %v", src, got, want)
		}
	}
}

func TestIsGeneratedSource_MarkerPastHeaderIgnored(t *testing.T) {
	src := "package x\n" + strings.Repeat("// filler\n", 1000) + "// Code generated by x. DO NOT EDIT.\n"
	if IsGeneratedSource([]byte(src)) {
		t.Error("marker far below the header should not count")
	}
}

func TestIsGeneratedName(t *testing.T) {
	cases := map[string]bool{
		"vendor.min.js":      true,
		"src/types/api.d.ts": true,
		"api/v1/user.pb.go":  true,
		"kind_string.go":     false,
		"src/App.tsx":        false,
		"internal/string.go": false,
		"main.go":            false,
		".d.ts":              false,
	}
	for path, want := range cases {
		if got := IsGeneratedName(path); got != want {
			t.Errorf("IsGeneratedName(%q) = %v, want %v", path, got, want)
		}
	}
}

func TestParallelMap_PreservesOrderAndFilters(t *testing.T) {
	t.Setenv("GIRL_JOBS", "4")
	items := make([]int, 500)
	for i := range items {
		items[i] = i
	}
	states := 0
	got := ParallelMap(items, func() *int { states++; return new(int) }, func(s *int, v int) (int, bool) {
		*s++
		return v * 2, v%3 != 0
	})
	want := 0
	for _, v := range items {
		if v%3 != 0 {
			if got[want] != v*2 {
				t.Fatalf("order broken at %d: got %d want %d", want, got[want], v*2)
			}
			want++
		}
	}
	if len(got) != want {
		t.Fatalf("len = %d, want %d", len(got), want)
	}
	if states != 4 {
		t.Fatalf("newState called %d times, want 4 (once per worker)", states)
	}
}

func TestParallelMap_Empty(t *testing.T) {
	got := ParallelMap([]string{}, func() struct{} { return struct{}{} }, func(struct{}, string) (int, bool) { return 0, true })
	if len(got) != 0 {
		t.Fatalf("expected empty result, got %v", got)
	}
}
